begin;
do $$
declare u uuid:='11111111-1111-1111-1111-111111111111'; other uuid:='22222222-2222-2222-2222-222222222222';h text:=repeat('c',64);ro text:=repeat('d',64);r jsonb;report jsonb;request jsonb;rows jsonb;app uuid;j text:='simplify-existing';
begin
 insert into private.agent_connections(user_id,name,token_hash,scopes,expires_at) values(u,'Import test',h,array['workspace:read','tracking:write'],now()+interval '1 hour'),(other,'Read only',ro,array['workspace:read'],now()+interval '1 hour');
 rows:='[{"company":"Example Systems","title":"Systems Intern","location":"Remote","url":"https://example.com/jobs/1?ref=Simplify&role=intern&utm_source=Simplify","status":"APPLIED","employmentType":"Internship","appliedDate":"2026-10-20","statusDate":"2026-10-20","archived":false,"archivedDate":null,"notes":"First note"},{"company":"Example Systems","title":"Systems Intern","location":"Remote","url":null,"status":"SAVED","employmentType":"Internship","appliedDate":null,"statusDate":"2026-10-21","archived":false,"archivedDate":null,"notes":"Another note"},{"company":"Example Compute","title":"Backend Engineer","location":"Remote","url":null,"status":"SAVED","employmentType":"FT","appliedDate":null,"statusDate":null,"archived":true,"archivedDate":"2026-10-21","notes":"Private note"}]';
 r:=public.agent_dispatch(h,'imports.preview',jsonb_build_object('rows',rows));
 if r->>'version'<>'0' or r->>'added'<>'2' or r->>'duplicateRows'<>'1' or exists(select 1 from public.imported_jobs where user_id=u) then raise exception 'Preview wrote history or missed duplicates: %',r;end if;
 request:=jsonb_build_object('rows',rows,'expectedVersion',0,'eventKey','simplify-test');
 report:=public.agent_dispatch(h,'imports.save',request);
 if report->>'added'<>'2' or public.agent_dispatch(h,'imports.save',request) is distinct from report then raise exception 'Import retry duplicated history';end if;
 if (select count(*) from public.imported_jobs where user_id=u)<>2 or exists(select 1 from public.jobs where canonical_url like 'https://example.com/jobs/1%') then raise exception 'Imported history leaked into shared jobs';end if;
 if not exists(select 1 from public.imported_jobs where record->>'status'='APPLIED' and record->>'notes' like '%Another note%' and jsonb_array_length(source_rows)=2 and record->>'url'='https://example.com/jobs/1?role=intern') then raise exception 'Source rows, notes or role URL lost';end if;
 if (public.agent_dispatch(h,'imports.list','{}')->>'version')<>'1' or jsonb_array_length(public.agent_dispatch(ro,'imports.list','{}')->'records')<>0 then raise exception 'Read back/owner isolation failed';end if;
 begin perform public.agent_dispatch(h,'imports.save',request||'{"eventKey":"stale"}');raise exception 'Stale version accepted';exception when serialization_failure then null;end;
 begin perform public.agent_dispatch(h,'imports.save',request||'{"rows":[]}');raise exception 'Changed retry accepted';exception when serialization_failure then null;end;
 begin perform public.agent_dispatch(ro,'imports.preview',jsonb_build_object('rows',rows));raise exception 'Read-only preview accepted';exception when insufficient_privilege then null;end;
 r:=public.agent_dispatch(h,'imports.save',request||'{"expectedVersion":1,"eventKey":"new-import"}');
 if r->>'added'<>'0' or r->>'skipped'<>'2' then raise exception 'Reimport changed existing records: %',r;end if;
 insert into public.jobs(id,canonical_url,employer) values(j,'https://example.com/jobs/existing','{"company":"Existing","title":"Engineer","location":"Remote"}');
 insert into public.applications(user_id,job_id,status) values(u,j,'Interview') returning id into app;
 perform public.agent_dispatch(h,'applications.progress',jsonb_build_object('applicationId',app,'expectedRevision',0,'status','Submitted','note','Reported submission','eventKey','existing-submit'));
 perform public.agent_dispatch(h,'applications.progress',jsonb_build_object('applicationId',app,'expectedRevision',(select revision from public.applications where id=app),'status','Interview','note','User-reported interview','eventKey','existing-interview'));
 r:=public.agent_dispatch(h,'imports.save',jsonb_build_object('expectedVersion',2,'eventKey','existing-app','rows',jsonb_build_array((rows->0)||'{"company":"Existing","title":"Engineer","url":"https://example.com/jobs/existing"}')));
 if r->>'added'<>'0' or r->>'skipped'<>'1' or (select status from public.applications where id=app)<>'Interview' or (select receipt from public.applications where id=app) is not null then raise exception 'Import overwrote application or forged receipt';end if;
 begin perform public.agent_dispatch(h,'imports.preview',jsonb_build_object('rows',jsonb_build_array((rows->0)||'{"url":"javascript:alert(1)"}')));raise exception 'Unsafe URL accepted';exception when invalid_parameter_value then null;end;
 begin perform public.agent_dispatch(h,'imports.preview',jsonb_build_object('rows',jsonb_build_array((rows->0)||'{"appliedDate":"2026-02-30"}')));raise exception 'Invalid date accepted';exception when datetime_field_overflow or invalid_parameter_value then null;end;
 begin perform public.agent_dispatch(h,'imports.preview',jsonb_build_object('rows',jsonb_build_array((rows->0)||'{"receipt":{},"status":"APPROVED"}')));raise exception 'Authority injection accepted';exception when invalid_parameter_value then null;end;
 perform set_config('test.uid',u::text,true);set local role authenticated;
 r:=public.simplify_import('list');if jsonb_array_length(r->'records')<>2 then raise exception 'Browser read differs from MCP';end if;
 r:=public.simplify_import('preview',jsonb_build_object('rows',rows));if r->>'skipped'<>'2' then raise exception 'Browser duplicate handling differs';end if;
 if (select count(*) from public.imported_jobs)<>2 then raise exception 'RLS leaked other history';end if;
 reset role;perform set_config('test.uid',other::text,true);set local role authenticated;
 if (select count(*) from public.imported_jobs)<>0 then raise exception 'Cross-owner read';end if;
 r:=public.simplify_import('save',jsonb_build_object('expectedVersion',0,'eventKey','other','rows',jsonb_build_array(rows->2)));if r->>'added'<>'1' then raise exception 'Browser import failed';end if;
 reset role;
 if not 'public.imported_jobs'=any(private.workspace_reset_tables()) then raise exception 'Import history missing from reset';end if;
 update private.agent_connections set revoked_at=now() where token_hash=h;
 begin perform public.agent_dispatch(h,'imports.list','{}');raise exception 'Revoked credential accepted';exception when invalid_authorization_specification then null;end;
end $$;
rollback;
